"""Markdown exports for demo plans and POV plans."""

from __future__ import annotations

from ..models import Account, Deal, DemoPlan, PovPlan, Requirement, SuccessCriterion, Task
from .pov_builder import summarise

FOOTER = (
    "\n---\n_Generated by SE Demo & POV Builder (community tool, not an official LogicMonitor "
    "product). Capability descriptions are community summaries; verify against official "
    "documentation._\n"
)
STATUS_LABEL = {
    "not_started": "Not started", "in_progress": "In progress", "met": "Met",
    "not_met": "Not met", "waived": "Waived",
}


def _bullets(items: list[str], indent: str = "") -> list[str]:
    return [f"{indent}- {i}" for i in items] or [f"{indent}- _None_"]


def demo_plan_markdown(plan: DemoPlan, deal: Deal, account: Account) -> str:
    c = plan.content
    lines = [
        f"# {plan.title}",
        "",
        f"**Account:** {account.name}{' (synthetic)' if account.is_synthetic else ''}  ",
        f"**Deal:** {deal.name}  ",
        f"**Version:** {plan.version} · **Duration:** {plan.duration_minutes} min · "
        f"**Generated:** {c.get('generated_at', '')[:16]} ({c.get('generator', '')})",
        "",
    ]
    if c.get("generic"):
        lines += ["> **Generic plan:** no discovery finding matched a scenario. Complete discovery to tailor it.", ""]
    lines += ["## Agenda", "", "| Start | Minutes | Item |", "|------:|--------:|------|"]
    for item in c.get("agenda", []):
        lines.append(f"| +{item['start_minute']} | {item['minutes']} | {item['title']} |")
    lines += ["", "## Customer pain points", ""]
    pains = c.get("pain_points", [])
    lines += _bullets([f"**{p['requirement']}** ({p['priority']}): {p['pain_point']}" for p in pains])
    for seg in c.get("segments", []):
        lines += ["", f"## {seg['title']} ({seg['minutes']} min)", "", seg["summary"], "",
                  f"_Why: {seg['selection_reason']}_", "", "**Demonstrates**", ""]
        lines += _bullets(seg["demonstrates"])
        caps = [f"{cap['name']}{'' if cap['verified'] else ' (unverified)'}" for cap in seg["capabilities"]]
        lines += ["", "**Capabilities:** " + ", ".join(caps), ""]
        if seg["linked_requirements"]:
            lines += ["**Linked requirements**", ""]
            lines += _bullets([f"{r['title']} ({r['priority']})" for r in seg["linked_requirements"]])
            lines.append("")
        lines += ["**Talking points**", ""]
        for tp in seg["talking_points"]:
            who = tp["audience"] + (f" — {', '.join(tp['stakeholders'])}" if tp["stakeholders"] else "")
            lines.append(f"- _{who}_")
            lines += _bullets(tp["points"], indent="  ")
    for heading, key in [
        ("Prerequisites", "prerequisites"), ("Data requirements", "data_requirements"),
        ("Preparation tasks", "prep_tasks"),
    ]:
        lines += ["", f"## {heading}", ""] + _bullets(c.get(key, []))
    lines += ["", "## Requirements not covered by this demo", ""]
    lines += _bullets([f"{r['title']} ({r['priority']})" for r in c.get("uncovered_requirements", [])])
    lines += ["", "## Assumptions", ""] + _bullets(c.get("assumptions", []))
    lines += ["", "## Missing evidence", ""] + _bullets(c.get("missing_evidence", []))
    if plan.notes:
        lines += ["", "## Notes", "", plan.notes]
    return "\n".join(lines) + "\n" + FOOTER


def pov_plan_markdown(
    plan: PovPlan,
    deal: Deal,
    account: Account,
    criteria: list[SuccessCriterion],
    milestones: list[Task],
    requirements: list[Requirement],
) -> str:
    summary = summarise(criteria, milestones, requirements)
    req_by_id = {r.id: r for r in requirements}
    lines = [
        f"# {plan.title}",
        "",
        f"**Account:** {account.name}{' (synthetic)' if account.is_synthetic else ''}  ",
        f"**Deal:** {deal.name}  ",
        f"**Dates:** {plan.start_date or 'TBD'} → {plan.end_date or 'TBD'} · **Status:** {plan.status}",
        "",
        "## Objectives",
        "",
        plan.objectives or "_Not yet defined_",
        "",
        "## Success summary",
        "",
        f"- Criteria met: **{summary['criteria_met']} of {summary['criteria_total']}** "
        f"(must-have: {summary['must_have_met']} of {summary['must_have_total']})",
        f"- Milestones closed: {summary['milestones_closed']} of {summary['milestones_total']}",
        f"- Evidence items: {summary['evidence_real']} real",
    ]
    if summary["evidence_simulated"]:
        lines.append(
            f"- **{summary['evidence_simulated']} simulated evidence item(s) excluded** — "
            "simulated results are not proof and are listed separately below."
        )
    lines += ["", "## Success criteria", "",
              "| # | Criterion | Requirement | Measurable outcome | Target | Validation | Owner | Status |",
              "|---|-----------|-------------|--------------------|--------|------------|-------|--------|"]
    for i, c in enumerate(criteria, 1):
        req = req_by_id.get(c.requirement_id or -1)
        cells = [str(i), c.title, f"{req.title} ({req.priority})" if req else "—",
                 c.measurable_outcome or "**TBD**", c.target or "—", c.validation_method or "**TBD**",
                 c.owner or "—", STATUS_LABEL.get(c.status, c.status)]
        lines.append("| " + " | ".join(x.replace("|", "/").replace("\n", " ") for x in cells) + " |")
    lines += ["", "## Validated evidence", ""]
    real = [(c, e) for c in criteria for e in c.evidence if not e.is_simulated]
    lines += _bullets([
        f"**{c.title}** — {e.description}" + (f" ({e.reference})" if e.reference else "")
        + f" · {e.evidence_type}" + (f", recorded by {e.recorded_by}" if e.recorded_by else "")
        for c, e in real
    ])
    simulated = [(c, e) for c in criteria for e in c.evidence if e.is_simulated]
    if simulated:
        lines += ["", "## Simulated items (NOT evidence)", "",
                  "_These were produced with mock data or simulations. They do not demonstrate results "
                  "in the customer's environment._", ""]
        lines += _bullets([f"{c.title} — {e.description}" for c, e in simulated])
    lines += ["", "## Milestones", "", "| Milestone | Responsible | Due | Status |",
              "|-----------|-------------|-----|--------|"]
    for m in sorted(milestones, key=lambda t: (t.due_date is None, t.due_date, t.id)):
        lines.append(f"| {m.title} | {m.owner} | {m.due_date or '—'} | {m.status} |")
    if plan.summary_notes:
        lines += ["", "## Notes", "", plan.summary_notes]
    return "\n".join(lines) + "\n" + FOOTER
